#!/usr/bin/env bash
set -euo pipefail

# claude/install.sh — install this repo into Claude Code (~/.claude/), the
# counterpart of ../install.sh for opencode. Run via `./install.sh --claude`.
# Idempotent; re-run after pulling or after editing agents/ or AGENTS.md.
#
#   skills/<name>        -> ~/.claude/skills/<name>   (shared with opencode)
#   claude/agents/*.md   -> ~/.claude/agents/         (generated by build.py)
#   claude/CLAUDE.md     -> ~/.claude/CLAUDE.md       (generated by build.py)
#   claude/settings.json    merged into ~/.claude/settings.json (not linked:
#                           Claude Code writes that file itself)
#   claude/mcp.sh           registers the MCP servers (skips existing ones)
#
# settings.json carries the two opencode.jsonc settings that still mean
# something here:
#   - deny `codegraph init/index/uninit`: index builds take minutes and GBs
#     of RAM and must go through ~/.config/opencode/scripts/codegraph-pilot.sh
#   - CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH=2 (opencode `subagent_depth: 2`):
#     orchestrator -> harness-pipeline -> leaf roles, and no deeper

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
CLAUDE_DIR="$HOME/.claude"
OPENCODE_SKILLS="$HOME/.config/opencode/skills"
TS="$(date +%Y%m%d-%H%M%S)"

source "$REPO/lib/link.sh"

echo "Installing Claude Code config from $REPO"
python3 "$REPO/claude/build.py"
echo ""

mkdir -p "$CLAUDE_DIR/skills" "$CLAUDE_DIR/agents"

skill_count=0
for skill_path in "$REPO"/skills/*/; do
    link_skill "${skill_path%/}" "$CLAUDE_DIR/skills/$(basename "$skill_path")"
    skill_count=$((skill_count + 1))
done

# Skills installed straight into opencode (real directories there, not
# symlinks into this repo) are shared too, so both tools see the same set.
extra_count=0
if [ -d "$OPENCODE_SKILLS" ]; then
    for skill_path in "$OPENCODE_SKILLS"/*/; do
        skill_path="${skill_path%/}"
        [ -L "$skill_path" ] && continue
        [ -f "$skill_path/SKILL.md" ] || continue
        # Already installed from skills/ above (a farm dir there would be
        # re-linked over itself).
        [ -d "$REPO/skills/$(basename "$skill_path")" ] && continue
        link "$skill_path" "$CLAUDE_DIR/skills/$(basename "$skill_path")"
        extra_count=$((extra_count + 1))
    done
fi

agent_count=0
for agent_file in "$REPO"/claude/agents/*.md; do
    link "$agent_file" "$CLAUDE_DIR/agents/$(basename "$agent_file")"
    agent_count=$((agent_count + 1))
done

link "$REPO/claude/CLAUDE.md" "$CLAUDE_DIR/CLAUDE.md"

# Deep-merge: objects merge, lists union (order kept), scalars from the repo.
python3 - "$REPO/claude/settings.json" "$CLAUDE_DIR/settings.json" <<'PY'
import json, sys
from pathlib import Path
src, dst = Path(sys.argv[1]), Path(sys.argv[2])
def merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        return {**a, **{k: merge(a[k], v) if k in a else v for k, v in b.items()}}
    if isinstance(a, list) and isinstance(b, list):
        return a + [x for x in b if x not in a]
    return b
current = json.loads(dst.read_text()) if dst.exists() else {}
dst.write_text(json.dumps(merge(current, json.loads(src.read_text())), indent=2) + "\n")
print(f"  merged {src.name} into {dst}")
PY

echo ""
"$REPO/claude/mcp.sh"

echo ""
echo "Done. Installed:"
echo "  - $skill_count repo skills + $extra_count opencode-only skills -> $CLAUDE_DIR/skills/"
echo "  - $agent_count agents -> $CLAUDE_DIR/agents/"
echo "  - CLAUDE.md, settings.json -> $CLAUDE_DIR/"
